def max_energy(beads):
    n = len(beads)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            if i + 1 == j:  # If a single bead is merged, the energy is the head value of the bead
                dp[i][j] = beads[i]
            else:
                max_energy = 0
                for k in range(i, j - 1):
                    # Try merging the current bead with each bead between index i and j-1
                    max_energy = max(max_energy, dp[i][k] * beads[k+1] * beads[j])
                if i + 2 == j:  # If two beads are merged, the energy is the product of the head value of the first bead and the tail value of the second bead
                    dp[i][j] = beads[i] * beads[j-1]
                else:
                    # Check if any bead between index i and j can be merged with any bead between index i+1 and j
                    for k in range(i + 2, j):
                        dp[i][j] = max(dp[i][j], dp[i][k] * beads[k+1] * beads[j])
    return dp[0][n-1]
```

