def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = ""
    for i, coeff in enumerate(coeffs[::-1]):
        if coeff == 0:
            continue
        if i == n:
            if coeff == 1:
                result += "x"
            else:
                result += f"{ coeff}x"
        elif coeff == -1:
            if i == 1:
                result += "-x"
            elif i == 0:
                result += "-1"
            else:
                result += f"{ coeff}x^{i}"
        elif coeff > 0:
            if i == 1:
                result += f"+{coeff}x"
            elif i == 0:
                result += f"+{coeff}"
            else:
                result += f"+{coeff}x^{i}"
        else:
            if i == 1:
                result += f"{coeff}-x"
            elif i == 0:
                result += f"{coeff-1}"
            else:
                result += f"{coeff}-x^{i}"
    return result
```

