def largest_prime_factor(n):
    if n < 2:
        raise ValueError("Input must be a positive integer greater than 1")

    factor = 2
    last_prime = 1
    while n > 1:
        if n % factor == 0:
            last_prime = factor
            n //= factor
            while n % factor == 0:
                n //= factor
        factor += 1
    return last_prime
