def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    memo[last] = 0
    if n <= 2:
        return 1
    if n % 2 == 0:
        memo[last] += count_sequences(n//2, last, memo)
    else:
        memo[last] += count_sequences(n//2, last, memo)
    return memo[last]
