def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 > y0:
        a, b = y0, x0
    else:
        a, b = x0, y0

    count = 0
    for i in range(1, int(b ** 0.5) + 1):
        if b % i == 0:
            if a // i == i:
                count += 1
            else:
                count += 2
    return count
