def calculate_score(system: int, points: str) -> list:
    game_scores = []
    team1_points = 0
    team2_points = 0
    lead = 0

    for char in points:
        if char == 'W':
            team1_points += 1
            lead += (team1_points - team2_points)
        elif char == 'L':
            team2_points += 1
            lead += (team2_points - team1_points)

        if lead >= (system // 2) and (lead == system or lead == system - 1):
            game_scores.append(f"{team1_points}:{team2_points}")
            lead = 0

    if lead != 0:
        game_scores.append(f"{team1_points}:{team2_points}")

    return game_scores
```

